<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$s=db()->prepare('SELECT * FROM owner_claims WHERE id=:id');$s->execute([':id'=>$id]);$claim=$s->fetch();if($claim&&in_array($action,['approve','reject'],true)){if($action==='approve'){$ownerCheck=db()->prepare('SELECT owner_user_id FROM listings WHERE id=:l');$ownerCheck->execute([':l'=>$claim['listing_id']]);$existingOwner=$ownerCheck->fetchColumn();if($existingOwner!==false&&$existingOwner!==null&&(int)$existingOwner!==(int)$claim['user_id']){flash('error','This listing is already assigned to another owner. Resolve the ownership conflict before approving.');redirect(app_path('admin/claims.php'));}db()->beginTransaction();try{db()->prepare("UPDATE owner_claims SET status='rejected',reviewed_by=:a,reviewed_at=CURRENT_TIMESTAMP WHERE listing_id=:l AND id<>:id AND status='pending'")->execute([':a'=>(int)$_SESSION['admin_id'],':l'=>$claim['listing_id'],':id'=>$id]);db()->prepare("UPDATE owner_claims SET status='approved',reviewed_by=:a,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id")->execute([':a'=>(int)$_SESSION['admin_id'],':id'=>$id]);db()->prepare("UPDATE listings SET owner_user_id=:u,verified=1,updated_at=CURRENT_TIMESTAMP WHERE id=:l")->execute([':u'=>$claim['user_id'],':l'=>$claim['listing_id']]);db()->prepare("UPDATE users SET role='owner' WHERE id=:u")->execute([':u'=>$claim['user_id']]);db()->commit();flash('success','Claim approved. The business listing is now assigned to this owner.');}catch(Throwable $e){db()->rollBack();throw $e;}}else{db()->prepare("UPDATE owner_claims SET status='rejected',reviewed_by=:a,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id")->execute([':a'=>(int)$_SESSION['admin_id'],':id'=>$id]);flash('success','Claim rejected.');}}redirect(app_path('admin/claims.php'));}
$status=(string)($_GET['status']??'pending');$allowed=['pending','approved','rejected'];$where=in_array($status,$allowed,true)?'WHERE c.status=:s':'';$s=db()->prepare('SELECT c.*,u.name user_name,u.email user_email,l.name listing_name,l.location listing_location FROM owner_claims c JOIN users u ON u.id=c.user_id JOIN listings l ON l.id=c.listing_id '.$where.' ORDER BY c.created_at DESC');if($where)$s->execute([':s'=>$status]);else$s->execute();$rows=$s->fetchAll();$adminTitle='Business ownership claims';include __DIR__.'/_header.php';?>
<div class="admin-panel"><div class="filter-row"><?php foreach($allowed as $x): ?><a class="filter-chip <?= $status===$x?'selected':'' ?>" href="<?= app_path('admin/claims.php?status='.$x) ?>"><?= ucfirst($x) ?></a><?php endforeach; ?></div><?php if($rows): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Applicant</th><th>Business</th><th>Contact supplied</th><th>Explanation</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= h($r['user_name']) ?></strong><small><?= h($r['user_email']) ?></small></td><td><strong><?= h($r['listing_name']) ?></strong><small><?= h($r['listing_location']) ?></small></td><td><?= h($r['business_email']) ?><small><?= h($r['business_phone']) ?></small></td><td><?= h(text_excerpt($r['message'],180)) ?></td><td><span class="status-pill status-<?= h($r['status']) ?>"><?= h(ucfirst($r['status'])) ?></span></td><td><?php if($r['status']==='pending'): ?><div class="row-actions"><form method="post" onsubmit="return confirm('Approve this ownership claim? Verify the applicant independently first.')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="approve"><button class="table-action">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="reject"><button class="table-action danger-text">Reject</button></form></div><?php else: ?><small><?= h($r['reviewed_at']??'') ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No claims in this queue.</p><?php endif; ?></div><?php include __DIR__.'/_footer.php';?>
